pub const ENTRY_COUNT: usize = 8810;

pub fn groups() -> &'static [Group] {
    GROUPS
}

pub fn find_group(anchor: &str) -> Option<&'static Group> {
    GROUPS
        .binary_search_by(|group| group.anchor.cmp(anchor))
        .ok()
        .map(|index| &GROUPS[index])
}
